package com.icbc.changzhou.ipam;

import com.google.gson.JsonObject;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicInteger;

/** Fourth-stage regression for manual assignment, responsibility scope, exports and gateway changes. */
public final class StageElevenManualAssignmentGatewaySmokeTest {
  public static void main(String[] args)throws Exception {
    Path work=Files.createTempDirectory("ipam-stage11-manual-gateway-"),db=work.resolve("stage11.db");
    migrate(db);seed(db);
    PhaseFourService phase4=new PhaseFourService(db);JsonObject plan=new JsonObject();plan.addProperty("branchId",1);plan.addProperty("outletId",1);plan.addProperty("productionCidr","108.56.32.0/24");phase4.createPlan(plan,1L);
    ManualAssignmentService manual=new ManualAssignmentService(db);PhaseTwoService phase2=new PhaseTwoService(db);PhaseThreeService phase3=new PhaseThreeService(db);
    long codeAsset=createAsset(phase4,"TECH","仅资源编码",0,1),userAsset=createAsset(phase4,"TECH","仅使用人",1,0),bothAsset=createAsset(phase4,"NON_TECH","编码和使用人",1,1),plainAsset=createAsset(phase4,"NON_TECH","无关联字段",0,0);
    long beforeApplications=count(db,"SELECT count(*) FROM ip_application");
    long available=pool(db,"AVAILABLE",(Long)null),disabled=pool(db,"AVAILABLE",available),reserved=pool(db,"AVAILABLE",available,disabled);phase2.updatePool(disabled,json("state","DISABLED"),1L);phase2.updatePool(reserved,json("state","MANUAL_RESERVED","reservationReason","盘点保留"),1L);
    long a1=register(manual,available,codeAsset,"TECH",null,null,"CODE-001",null,null,null);releaseAdmin(phase3,a1,"释放可用补录");assertState(phase4,available,"AVAILABLE");
    long a2=register(manual,disabled,userAsset,"TECH","张三","AUTH-001",null,null,null,null);releaseAdmin(phase3,a2,"释放停用补录");assertState(phase4,disabled,"DISABLED");
    long a3=register(manual,reserved,bothAsset,"NON_TECH","李四","AUTH-002","BOTH-001",null,null,null);releaseAdmin(phase3,a3,"释放人工保留补录");assertState(phase4,reserved,"MANUAL_RESERVED");
    if(count(db,"SELECT count(*) FROM ip_application")!=beforeApplications)throw new AssertionError("manual registration must not create a fake application");
    long duplicate=pool(db,"AVAILABLE",available,disabled,reserved);long duplicateAssignment=register(manual,duplicate,plainAsset,"NON_TECH",null,null,null,null,null,null);
    boolean duplicateRejected=false;try{manual.register(duplicate,body(plainAsset,"NON_TECH",null,null,null,null,null,null),1L);}catch(PhaseTwoService.Problem e){duplicateRejected="IP_ALREADY_ASSIGNED".equals(e.code);}if(!duplicateRejected)throw new AssertionError("duplicate manual registration must be rejected");
    boolean gatewayRejected=false;try{manual.register(pool(db,"SYSTEM_RESERVED",(Long)null),plain(plainAsset,"NON_TECH"),1L);}catch(PhaseTwoService.Problem e){gatewayRejected="SYSTEM_RESERVED_PROTECTED".equals(e.code);}if(!gatewayRejected)throw new AssertionError("current gateway must reject ordinary manual registration");
    releaseAdmin(phase3,duplicateAssignment,"释放重复回归地址");
    long responsiblePool=pool(db,"AVAILABLE",available,disabled,reserved,duplicate);Map<String,Object> responsibleOptions=manual.options(responsiblePool);if(((List<?>)responsibleOptions.get("responsibleTechAdmins")).isEmpty())throw new AssertionError("active tech administrator option missing");
    long responsibleAssignment=((Number)manual.register(responsiblePool,body(plainAsset,"NON_TECH",null,null,null,2L,"GE0/0/9","现场核对"),1L).get("id")).longValue();Map<String,Object> responsibleRow=poolItem(phase4,responsiblePool);if(!"MANUAL_REGISTRATION".equals(responsibleRow.get("assignmentSource"))||!"admin11".equals(responsibleRow.get("manualRegistrar"))||!"tech11".equals(responsibleRow.get("responsibleTech")))throw new AssertionError("manual source or responsibility snapshot missing");
    List<Map<String,Object>> techRows=phase3.myAssignments(2L);if(techRows.size()!=1||!"MANUAL_REGISTRATION".equals(techRows.get(0).get("assignmentSource"))||techRows.get(0).containsKey("switchPort"))throw new AssertionError("responsible tech visibility or port privacy failed");
    releaseTech(phase3,responsibleAssignment,"科技管理员回收补录");assertState(phase4,responsiblePool,"AVAILABLE");
    long noResponsible=pool(db,"AVAILABLE",available,disabled,reserved,duplicate,responsiblePool);long noResponsibleAssignment=((Number)manual.register(noResponsible,body(plainAsset,"NON_TECH",null,null,null,null,"GE0/0/10",null),1L).get("id")).longValue();if(!phase3.myAssignments(2L).isEmpty())throw new AssertionError("manual assignment without responsibility leaked to tech administrator");releaseAdmin(phase3,noResponsibleAssignment,"管理员回收无责任人补录");
    String assignmentCsv=new String(phase3.exportManualAware("ASSIGNMENT","CSV",new LinkedHashSet<String>(),Collections.<String,String>emptyMap(),1L),StandardCharsets.UTF_8);if(!assignmentCsv.contains("assignmentSource")||!assignmentCsv.contains("MANUAL_REGISTRATION")||!assignmentCsv.contains("registeredBy"))throw new AssertionError("manual assignment export fields missing");
    String releaseCsv=new String(phase3.exportManualAware("RELEASE","CSV",new LinkedHashSet<String>(),Collections.<String,String>emptyMap(),1L),StandardCharsets.UTF_8);if(!releaseCsv.contains("sourcePoolState")||!releaseCsv.contains("registeredAt"))throw new AssertionError("manual release export fields missing");
    gatewayCases(db,manual,phase2,phase4,phase3,plainAsset);
    concurrentManual(db,manual,plainAsset);
    if(count(db,"SELECT count(*) FROM ip_assignment WHERE status='ASSIGNED'")<0)throw new AssertionError("assignment count query failed");if(count(db,"SELECT count(*) FROM audit_log WHERE action='ADJUST_GATEWAY'")<3)throw new AssertionError("gateway audit records missing");
    System.out.println("PASS|STAGE11_MANUAL_ASSIGNMENT_GATEWAY_SOURCE_SCOPE_EXPORT_CONCURRENCY|"+work);
  }
  private static void migrate(Path db)throws Exception{Class<?> type=Class.forName("com.icbc.changzhou.ipam.IpamApplication$Database");java.lang.reflect.Constructor<?> ctor=type.getDeclaredConstructor(Path.class);ctor.setAccessible(true);Object runtime=ctor.newInstance(db);java.lang.reflect.Method method=type.getDeclaredMethod("migrate");method.setAccessible(true);method.invoke(runtime);}
  private static void seed(Path db)throws Exception{try(Connection c=open(db);Statement s=c.createStatement()){s.execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password,is_initial_admin) VALUES('admin11','x','管理员','ADMIN',1,0,1)");s.execute("INSERT INTO branch(code,name,is_active) VALUES('B11','阶段四支行',1)");s.execute("INSERT INTO outlet(branch_id,code,name,is_active) VALUES(1,'O11','阶段四网点',1)");s.execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password,is_initial_admin,branch_id,outlet_id) VALUES('tech11','x','科技管理员','TECH_ADMIN',1,0,0,1,1)");}}
  private static long createAsset(PhaseFourService service,String type,String name,int user,int code)throws Exception{JsonObject b=new JsonObject();b.addProperty("assetType",type);b.addProperty("name",name);b.addProperty("requiresUser",user);b.addProperty("requiresResourceCode",code);b.addProperty("recommendedRangeType","OFFICE");b.addProperty("active",1);return ((Number)service.createAsset(b,1L).get("id")).longValue();}
  private static JsonObject json(String... values){JsonObject x=new JsonObject();for(int i=0;i+1<values.length;i+=2)x.addProperty(values[i],values[i+1]);return x;}
  private static JsonObject body(long asset,String type,String user,String auth,String code,Long responsible,String port,String note){JsonObject x=new JsonObject();x.addProperty("assetId",asset);x.addProperty("assetType",type);if(user!=null)x.addProperty("userName",user);if(auth!=null)x.addProperty("userUnifiedAuthId",auth);if(code!=null)x.addProperty("assetCode",code);if(responsible!=null)x.addProperty("responsibleTechUserId",responsible.longValue());if(port!=null)x.addProperty("switchPort",port);if(note!=null)x.addProperty("note",note);return x;}
  private static JsonObject plain(long asset,String type){return body(asset,type,null,null,null,null,null,null);}
  private static long register(ManualAssignmentService service,long pool,long asset,String type,String user,String auth,String code,Long responsible,String port,String note)throws Exception{return ((Number)service.register(pool,body(asset,type,user,auth,code,responsible,port,note),1L).get("id")).longValue();}
  private static void releaseAdmin(PhaseThreeService service,long id,String reason)throws Exception{service.forceRelease(id,1L,reason,UUID.randomUUID().toString());}
  private static void releaseTech(PhaseThreeService service,long id,String reason)throws Exception{service.release(id,2L,reason,UUID.randomUUID().toString());}
  private static void assertState(PhaseFourService service,long pool,String expected)throws Exception{Map<String,Object> item=poolItem(service,pool);if(!expected.equals(item.get("state")))throw new AssertionError("expected "+expected+" got "+item.get("state"));}
  private static Map<String,Object> poolItem(PhaseFourService service,long id)throws Exception{Map<String,Object> first=service.pool(null,null,null,"",1);int pages=(int)Math.ceil(((Number)first.get("total")).doubleValue()/((Number)first.get("pageSize")).doubleValue());for(int page=1;page<=Math.max(1,pages);page++){Map<String,Object> rows=page==1?first:service.pool(null,null,null,"",page);for(Map<String,Object> row:(List<Map<String,Object>>)rows.get("items"))if(((Number)row.get("id")).longValue()==id)return row;}throw new AssertionError("pool item not found: "+id);}
  private static long pool(Path db,String state,Long...exclude)throws Exception{Set<Long> used=new HashSet<Long>();for(Long x:exclude)if(x!=null)used.add(x);StringBuilder sql=new StringBuilder("SELECT p.id FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id LEFT JOIN ip_assignment d ON d.ip_pool_id=p.id AND d.status='ASSIGNED' WHERE p.deleted_at IS NULL AND d.id IS NULL");if("AVAILABLE".equals(state))sql.append(" AND p.ip_address<>r.gateway AND p.is_active=1 AND p.is_reserved=0");else if("SYSTEM_RESERVED".equals(state))sql.append(" AND p.ip_address=r.gateway");else throw new IllegalArgumentException(state);sql.append(" ORDER BY p.id");try(Connection c=open(db);Statement s=c.createStatement();ResultSet r=s.executeQuery(sql.toString())){while(r.next()){long id=r.getLong(1);if(!used.contains(id))return id;}}throw new AssertionError("no pool for "+state);}
  private static void gatewayCases(Path db,ManualAssignmentService manual,PhaseTwoService phase2,PhaseFourService phase4,PhaseThreeService phase3,long plainAsset)throws Exception{List<Long> ranges=new ArrayList<Long>();try(Connection c=open(db);Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id FROM ip_range WHERE outlet_id=1 ORDER BY id")){while(r.next())ranges.add(r.getLong(1));}if(ranges.size()<4)throw new AssertionError("six planned ranges missing");for(int i=0;i<3;i++){long range=ranges.get(i),target=target(db,range);if(i==1)phase2.updatePool(target,json("state","DISABLED"),1L);if(i==2)phase2.updatePool(target,json("state","MANUAL_RESERVED","reservationReason","网关迁移测试"),1L);Map<String,Object> before=rangeRow(db,range);Map<String,Object> changed=manual.adjustGateway(range,json("newGateway",String.valueOf(poolAddress(db,target))),1L);if(!Boolean.TRUE.equals(changed.get("changed")))throw new AssertionError("gateway change did not execute");if(!String.valueOf(changed.get("oldGateway")).equals(String.valueOf(before.get("gateway"))))throw new AssertionError("old gateway snapshot missing");assertPoolState(db,target,"SYSTEM_RESERVED");assertPoolState(db,((Number)before.get("gatewayPoolId")).longValue(),"AVAILABLE");Map<String,Object> same=manual.adjustGateway(range,json("newGateway",String.valueOf(poolAddress(db,target))),1L);if(!Boolean.FALSE.equals(same.get("changed")))throw new AssertionError("same gateway must be idempotent");}
    long range=ranges.get(3),crossTarget=target(db,ranges.get(4));boolean cross=false;String crossCode="";try{manual.adjustGateway(range,json("newGateway",String.valueOf(poolAddress(db,crossTarget))),1L);}catch(PhaseTwoService.Problem e){crossCode=e.code;cross="GATEWAY_TARGET_NOT_FOUND".equals(e.code)||"GATEWAY_OUT_OF_RANGE".equals(e.code);}if(!cross)throw new AssertionError("cross-range gateway target must be rejected: "+crossCode);
    long assignedTarget=target(db,range);manual.register(assignedTarget,plain(plainAsset,"NON_TECH"),1L);long assignment=findAssignment(db,assignedTarget);boolean assigned=false;try{manual.adjustGateway(range,json("newGateway",String.valueOf(poolAddress(db,assignedTarget))),1L);}catch(PhaseTwoService.Problem e){assigned="GATEWAY_TARGET_ASSIGNED".equals(e.code);}if(!assigned)throw new AssertionError("assigned gateway target must be rejected");releaseAdmin(phase3,assignment,"释放网关目标回归");}
  private static void concurrentManual(Path db,ManualAssignmentService service,long asset)throws Exception{long id=pool(db,"AVAILABLE");final CountDownLatch start=new CountDownLatch(1);final AtomicInteger success=new AtomicInteger(),conflict=new AtomicInteger();List<Thread> threads=new ArrayList<Thread>();for(int i=0;i<2;i++){Thread t=new Thread(()->{try{start.await();service.register(id,plain(asset,"NON_TECH"),1L);success.incrementAndGet();}catch(Exception e){if(e instanceof PhaseTwoService.Problem&&"IP_ALREADY_ASSIGNED".equals(((PhaseTwoService.Problem)e).code))conflict.incrementAndGet();else throw new RuntimeException(e);}});threads.add(t);t.start();}start.countDown();for(Thread t:threads)t.join();if(success.get()!=1||conflict.get()!=1)throw new AssertionError("concurrent manual registration must have one winner");}
  private static long target(Path db,long range)throws Exception{try(Connection c=open(db);PreparedStatement p=c.prepareStatement("SELECT p.id FROM ip_address_pool p WHERE p.ip_range_id=? AND p.is_active=1 AND p.is_reserved=0 ORDER BY p.id LIMIT 1")){p.setLong(1,range);try(ResultSet r=p.executeQuery()){if(!r.next())throw new AssertionError("gateway target missing");return r.getLong(1);}}}
  private static String poolAddress(Path db,long id)throws Exception{try(Connection c=open(db);PreparedStatement p=c.prepareStatement("SELECT ip_address FROM ip_address_pool WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){r.next();return r.getString(1);}}}
  private static Map<String,Object> rangeRow(Path db,long id)throws Exception{try(Connection c=open(db);PreparedStatement p=c.prepareStatement("SELECT r.gateway,(SELECT p.id FROM ip_address_pool p WHERE p.ip_range_id=r.id AND p.ip_address=r.gateway) AS gatewayPoolId FROM ip_range r WHERE r.id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){r.next();Map<String,Object> x=new HashMap<String,Object>();x.put("gateway",r.getString(1));x.put("gatewayPoolId",r.getLong(2));return x;}}}
  private static void assertPoolState(Path db,long id,String state)throws Exception{try(Connection c=open(db);PreparedStatement p=c.prepareStatement("SELECT CASE WHEN d.id IS NOT NULL THEN 'ASSIGNED' WHEN p.ip_address=r.gateway THEN 'SYSTEM_RESERVED' WHEN p.is_reserved=1 THEN 'MANUAL_RESERVED' WHEN p.is_active=1 THEN 'AVAILABLE' ELSE 'DISABLED' END FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id LEFT JOIN ip_assignment d ON d.ip_pool_id=p.id AND d.status='ASSIGNED' WHERE p.id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){r.next();if(!state.equals(r.getString(1)))throw new AssertionError("pool state mismatch: "+id+" expected="+state+" actual="+r.getString(1));}}}
  private static long findAssignment(Path db,long pool)throws Exception{try(Connection c=open(db);PreparedStatement p=c.prepareStatement("SELECT id FROM ip_assignment WHERE ip_pool_id=? AND status='ASSIGNED'")){p.setLong(1,pool);try(ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}}
  private static long count(Path db,String sql)throws Exception{try(Connection c=open(db);Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
  private static Connection open(Path db)throws Exception{Connection c=DriverManager.getConnection("jdbc:sqlite:"+db);try(Statement s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");s.execute("PRAGMA busy_timeout=5000");}return c;}
}
